fn bitwise_or(a: Vec<u8>, b: Vec<u8>) -> Vec<u8> {
    // Assumption per problem statement: a.len() == b.len()
    // If you want to enforce it defensively, uncomment:
    // assert_eq!(a.len(), b.len());

    a.iter()
        .zip(b.iter())
        .map(|(&x, &y)| x | y)
        .collect()
}

